<?php
/**
 * Generates a Bricks provider-excerpt fixture for the perf-a / perf-b pin tests.
 *
 * Usage (read-only on the theme):
 *   php tests/fixtures/bricks-provider-acf/extract.php <path/to/themes/bricks> <out-file>
 *
 * The fixture carries, verbatim and line-for-line, every Bricks method that
 * ProviderFingerprint hashes (perf-a: six methods; perf-b: four), wrapped in
 * the smallest class scaffold that lets them run without WordPress. Because
 * the pinned methods are copied byte-for-byte, ProviderFingerprint computes
 * the same hashes from the fixture as from the installed theme — the tests
 * assert that, so a fixture can never drift from the code it stands in for.
 *
 * The scaffold's register_tags() replays `Provider_Acf::$fixture_fields`
 * instead of reading ACF; that method is not pinned and is inherited
 * unchanged by IndexedAcfProvider, so it does not affect the comparison.
 *
 * To pin a new Bricks release: run this against the new theme, add the hash
 * to ProviderFingerprint, add a vendored register_tag variant, and add the
 * fixture to BricksProviderPins::FIXTURES in the parity harness.
 */

if (PHP_SAPI !== 'cli') {
    exit(1);
}

if ($argc !== 3) {
    fwrite(STDERR, "usage: php extract.php <bricks-theme-dir> <out-file>\n");
    exit(2);
}

$theme = rtrim($argv[1], '/');
$out = $argv[2];

if (! defined('ABSPATH')) {
    define('ABSPATH', '/dbvc-fixture-extract/');
}

$dir = $theme . '/includes/integrations/dynamic-data';
foreach (['providers/provider-interface.php', 'providers/base.php', 'providers/provider-acf.php', 'providers.php'] as $file) {
    require $dir . '/' . $file;
}

$version = 'unknown';
if (is_readable($theme . '/style.css') && preg_match('/^Version:\s*(\S+)/mi', (string) file_get_contents($theme . '/style.css'), $m)) {
    $version = $m[1];
}

$acf = 'Bricks\\Integrations\\Dynamic_Data\\Providers\\Provider_Acf';
$base = 'Bricks\\Integrations\\Dynamic_Data\\Providers\\Base';
$providers = 'Bricks\\Integrations\\Dynamic_Data\\Providers';

/**
 * @return string verbatim source lines of one method
 */
function dbvc_fixture_method($class, $method)
{
    $reflection = new ReflectionMethod($class, $method);
    $lines = file($reflection->getFileName());

    return implode('', array_slice($lines, $reflection->getStartLine() - 1, $reflection->getEndLine() - $reflection->getStartLine() + 1));
}

$constants = '';
foreach ((new ReflectionClass('Bricks\\Integrations\\Dynamic_Data\\Providers\\Provider_Interface'))->getConstants() as $name => $value) {
    $constants .= "\t\tconst {$name} = " . var_export($value, true) . ";\n";
}

$acf_methods = '';
foreach (['register_tag', 'get_nested_parent_group_field_data', 'get_fields_by_context', 'get_flexible_content_parent_layout_data', 'get_fields', 'get_fields_locations', 'required_hooks', 'flush_cache'] as $method) {
    $acf_methods .= "\n" . dbvc_fixture_method($acf, $method);
}

$fixture = "<?php\n"
    . "// phpcs:ignoreFile\n"
    . "/*\n"
    . " * TEST FIXTURE — never loaded by the plugin. Generated by extract.php from\n"
    . " * Bricks {$version} (themes/bricks/includes/integrations/dynamic-data/,\n"
    . " * GPL-2.0-or-later, (c) Bricks Builder). The methods ProviderFingerprint pins\n"
    . " * are copied verbatim; everything else is a minimal scaffold. Do not edit by\n"
    . " * hand — regenerate.\n"
    . " */\n\n"
    . "namespace Bricks\\Integrations\\Dynamic_Data\\Providers {\n\n"
    . "\tinterface Provider_Interface {\n{$constants}\t}\n\n"
    . "\tabstract class Base implements Provider_Interface {\n"
    . "\t\tprotected \$name;\n\n\t\tpublic \$tags = [];\n\n\t\tpublic \$loop_tags = [];\n\n"
    . dbvc_fixture_method($base, '__construct')
    . "\n\t\tpublic function add_control_options( \$control_options ) { return \$control_options; }\n"
    . "\t\tpublic function set_loop_query( \$results, \$query ) { return \$results; }\n"
    . "\t\tpublic function set_loop_object( \$loop_object, \$loop_key, \$query ) { return \$loop_object; }\n"
    . "\t}\n\n"
    . "\tclass Provider_Acf extends Base {\n"
    . "\t\t/** @var array<int, array<string, mixed>> scaffold: the field list register_tags() replays */\n"
    . "\t\tpublic static \$fixture_fields = [];\n\n"
    . "\t\tpublic function register_tags() {\n"
    . "\t\t\tforeach ( self::\$fixture_fields as \$field ) {\n"
    . "\t\t\t\t\$this->register_tag( \$field );\n"
    . "\t\t\t}\n"
    . "\t\t}\n"
    . $acf_methods
    . "\t}\n"
    . "}\n\n"
    . "namespace Bricks\\Integrations\\Dynamic_Data {\n\n"
    . "\tclass Providers {\n"
    . "\t\tprivate static \$providers = [];\n\n"
    . "\t\tpublic static function get_registered_provider( \$provider ) { return self::\$providers[ \$provider ] ?? null; }\n\n"
    . dbvc_fixture_method($providers, 'register')
    . "\t}\n"
    . "}\n";

if (file_put_contents($out, $fixture) === false) {
    fwrite(STDERR, "could not write {$out}\n");
    exit(1);
}

fwrite(STDOUT, "Bricks {$version} -> {$out}\n");
